using System.Collections.Generic;
using LittleLeo.Events;
using NaughtyAttributes;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "MapHistory", menuName = "Data/Map/MapHistory")]
public class MapHistory : ScriptableObject
{
	public const int NO_INDEX = -1;

	public const int ANY_INDEX = -2;

	[SerializeField]
	private SaveSystem saveSystem;

	[SerializeField]
	private MapHandler mapHandler;

	[SerializeField]
	private VoidEvent fetchMapHistoryEvent;

	public AreaDatas AreaDatas;

	public List<AreaData> VisitedArea => AreaDatas.VisitedAreas;

	private int currentAreaIndex => mapHandler.CurrentAreaIndex;

	public void SetVisitedNode(int levelIndex, int visitedNodeIndex, string infoNode, bool isAstreaSecondPhase = false)
	{
		if (VisitedArea[currentAreaIndex].visitedNodes.Count - 1 != levelIndex || isAstreaSecondPhase)
		{
			VisitedArea[currentAreaIndex].visitedNodes.Add(new NodeHistoryData(levelIndex, visitedNodeIndex, infoNode));
		}
	}

	public NodeHistoryData GetLastVisitedNode()
	{
		if (currentAreaIndex < VisitedArea.Count && VisitedArea[currentAreaIndex].visitedNodes.Count > 0)
		{
			return VisitedArea[currentAreaIndex].visitedNodes[VisitedArea[currentAreaIndex].visitedNodes.Count - 1];
		}
		return null;
	}

	public int GetVisitedNode(int levelIndex)
	{
		if (!IsValidRange(levelIndex))
		{
			return -1;
		}
		return VisitedArea[currentAreaIndex].visitedNodes[levelIndex].nodeIndex;
	}

	public bool IsValidRange(int levelIndex)
	{
		if (levelIndex >= 0)
		{
			return levelIndex < VisitedArea[currentAreaIndex].visitedNodes.Count;
		}
		return false;
	}

	[Button("Unvisit All")]
	public void OnResetToStartRunState()
	{
		VisitedArea.Clear();
		VisitedArea.Add(new AreaData(new List<NodeHistoryData>()));
	}

	[Button("NextArea")]
	public void SetupNextAreaAndSaveMapHistory()
	{
		VisitedArea.Add(new AreaData(new List<NodeHistoryData>()));
		saveSystem.SaveMapHistory(saveAndStoreCache: true);
	}

	[Button("Fetch History")]
	private void FetchMapHistory()
	{
		fetchMapHistoryEvent?.Raise();
	}

	[Button("Load Map History")]
	private void LoadMapHistory()
	{
		saveSystem.LoadMapHistory();
	}
}
